	scwin.checkRowValues = function() {
		const tbody = WebSquare.wUnit.getDomById('gridView1_body_tbody');
		let isLastRowFound = false;
		const expectedValues = ["나", "가", "나", "나", "가"];
		let actualValues = [];
		let reValue = false;

		const rows = Array.from(tbody.querySelectorAll('tr'));
		rows.forEach((row, index) => {
			if (row.classList.contains('w2grid_hidedRow')) {
				isLastRowFound = true;
			}

			if (!isLastRowFound) {
				if (row.style.display === 'none') {
					return;
				}
				const td = row.querySelector('td');
				if (td) {
					const value = td.innerText.trim();
					actualValues.push(value);
				}
			}
		});

		if (JSON.stringify(actualValues) === JSON.stringify(expectedValues)) {
			console.log('값이 일치합니다:', actualValues);
			reValue = true;
		} else {
			console.log('값이 일치하지 않습니다:', actualValues);
			reValue = false;
		}
		return reValue;
	}

	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('span1').innerText == "1010110";
	}		
	scwin.checkVal2 = function() {
		return scwin.checkRowValues();
	}		

	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()","true");
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()","true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
